public class LongArrayUtil {

    /**
     * Return a hash code based on the contents of the specified array. If
     * {@code array} is {@code null}, this method returns 0.
     *
     * @param array the long array to obtain a hashcode
     * @return the long array's hashcode, which could be 0 if the array is null
     */
    public static int nullSafeHashCode(long[] array) {
        if (array == null) {
            return 0;
        }
        int hash = 7;
        hash = 31 * hash + array.length;
        for (int i = 0; i < array.length; i++) {
            hash = 31 * hash + (int) (array[i] ^ (array[i] >>> 32));
        }
        return hash;
    }

}

