static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 100000000);
    int month = (int) ((timeBucket - year * 100000000) / 10000);
    int day = (int) ((timeBucket - year * 100000000 - month * 10000) / 100);
    int hour = (int) ((timeBucket - year * 100000000 - month * 10000 - day * 100) / 10000);
    int minute = (int) ((timeBucket - year * 100000000 - month * 10000 - day * 100 - hour * 10000) / 100);
    int second = (int) (timeBucket - year * 100000000 - month * 10000 - day * 100 - hour * 10000 - minute * 100);
    int millisecond = (int) (timeBucket % 1000);

    // Compress the time bucket
    timeBucket = (long) (year * 100000000 + month * 10000 + day * 100 + hour * 10000 + minute * 100 + second * 100 + millisecond);

    // Adjust the time bucket based on the day step
    timeBucket = timeBucket - (dayStep - 1) * 1000000;

    return timeBucket;
}

public static long compressTimeBucket (long timeBucket, int dayStep) {
	// Calculate the year and month of the time bucket
	int year = (int) (timeBucket / 10000);
	int month = (int) ((timeBucket % 10000) / 100);

	// Calculate the day of the month
	int day = (int) (timeBucket % 100);

	// Re-format the time bucket according to the day step
	int newDay;
	if (dayStep == 11) {
		newDay = day - (day % 10);
		if (newDay == 0) {
			newDay = 10;
		}
	} else {
		newDay = day;
	}

	// Build the re-formatted time bucket
	long newTimeBucket = (long) (year * 10000 + month * 100 + newDay);

	return newTimeBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Truncate the time bucket to the dayStep interval
    long dayInterval = 1000 * 60 * 60 * 24 * dayStep;
    timeBucket = timeBucket / dayInterval * dayInterval;

    // If the dayStep is 1, return the original time bucket
    if (dayStep == 1) {
        return timeBucket;
    }

    // Repeat the process for the next lower dayStep value
    return compressTimeBucket(timeBucket, dayStep - 1);
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the time bucket's year, month, and day
    int year = (int) (timeBucket / 100000000);
    int month = (int) ((timeBucket - (year * 100000000)) / 1000000);
    int day = (int) ((timeBucket - (year * 100000000) - (month * 1000000)));

    // Adjust the day by the day step
    day += dayStep;

    // Check if the day is valid
    if (day < 1 || day > 28) {
        throw new IllegalArgumentException("Day is invalid: " + day);
    }

    // Return the re-formatted time bucket
    return (year * 100000000) + (month * 1000000) + (day * 1000000);
}

