public static int computeUTF8Size(CharSequence str, int index, int len) {
    int utflen = 0;
    int i = index;

    for (int j = 0; j < len; j++) {
        int c = str.charAt(i);
        if (c >= 0x0001 && c <= 0x007F) {
            utflen++;
        } else if (c > 0x07FF) {
            utflen += 3;
        } else {
            utflen += 2;
        }

        if (Character.isHighSurrogate(c)) {
            utflen++;
            i++;
        }

        i++;
    }

    return utflen;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;
    for (int i = index; i < len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            ++i;
            if (Character.isLowSurrogate(str.charAt(i))) {
                size += 4;
            } else {
                throw new IllegalArgumentException("Invalid low surrogate");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

