public ByteVector putByteArray(byte[] byteArrayValue,int byteOffset,int byteLength) {
    // Check if the byte array is empty
    if (byteArrayValue == null || byteLength == 0) {
        // If so, simply return the byte vector
        return this;
    }

    // Check if the byte offset is valid
    if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
        // If not, throw an IllegalArgumentException
        throw new IllegalArgumentException("Byte offset is invalid: " + byteOffset);
    }

    // Check if the number of bytes to copy is valid
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        // If not, throw an IllegalArgumentException
        throw new IllegalArgumentException("Number of bytes to copy is invalid: " + byteLength);
    }

    // Calculate the new size of this byte vector
    int newSize = this.size + byteLength;

    // Check if the new size is larger than the capacity
    if (newSize > this.capacity) {
        // If so, increase the capacity
        this.capacity = Math.max(this.capacity * 2, newSize);

        // And create a new buffer with the new capacity
        this.buffer = Arrays.copyOf(this.buffer, this.capacity);
    }

    // Copy the bytes from the byte array to this byte vector
    System.arraycopy(byteArrayValue, byteOffset, this.buffer, this.size, byteLength);

    // Update the size of this byte vector
    this.size = newSize;

    // Return this byte vector
    return this;
}

