public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String path = u.getPath();
    if (!decode) {
        return getPathSegments(path);
    } else {
        String decodedPath = URLDecoder.decode(path, "UTF-8");
        return getPathSegments(decodedPath);
    }
}

public static List<PathSegmentImpl> getPathSegments(String path) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    int length = path.length();
    if (!path.isEmpty()) {
        if (path.startsWith("/")) {
            // Ignore leading slash
            path = path.substring(1);
            length -= 1;
        }
        if (length > 0) {
            boolean prevDelimiter = false;
            char prevChar;
            int startIndex = 0;
            for (int i = 0; i < length; i++) {
                char c = path.charAt(i);
                if (c == '/') {
                    if (!prevDelimiter) {
                        startIndex = i;
                    }
                    prevDelimiter = true;
                } else {
                    prevDelimiter = false;
                }
                if (i == length - 1) {
                    segments.add(new PathSegmentImpl(path.substring(startIndex, i + 1)));
                }
            }
        } else {
            segments.add(new PathSegmentImpl(""));
        }
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    if ("/".equals(u.getPath())) { //Handle case where path is empty
        return pathSegments;
    }
    boolean isAbsolutePath = u.getPath().startsWith("/");
    String[] segments = u.getPath().split("/"); //Split path into segments
    for (String segment : segments) {
        if (segment.equals("")) { //Skip over empty segments
            continue;
        }
        String decodedSegment = decode ? URLDecoder.decode(segment, "UTF-8") : segment;
        pathSegments.add(new PathSegmentImpl(decodedSegment));
    }
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
	String path = u.getPath();
	List<PathSegmentImpl> segments = new ArrayList<>();

	// Ignore the leading '/' if the path component is an absolute path component
	if (path.charAt(0) == '/' && isAbsolutePath(path)) {
		path = path.substring(1);
	}

	// Iterate through the path segments
	for (String segment : path.split("/")) {
		// Decode the path segment if needed
		if (decode) {
			segment = URLDecoder.decode(segment, "UTF-8");
		}
		segments.add(new PathSegmentImpl(segment));
	}

	return segments;
}

