    if (str == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i < str.length() - 1) {
                char next = str.charAt(i + 1);
                if (next == 'n') {
                    result.append('\n');
                    i++; // skip next character
                } else if (next == 'r') {
                    result.append('\r');
                    i++; // skip next character
                } else if (next == 't') {
                    result.append('\t');
                    i++; // skip next character
                } else if (next == '\\') {
                    result.append('\\');
                    i++; // skip next character
                } else if (next == '\'') {
                    result.append('\');
                    i++; // skip next character
                } else {
                    throw new Exception("Invalid escape sequence: " + next);
                }
            }
        } else {
            result.append(ch);
        }
    }

    return result.toString();
}

