private int computeBinaryLog(int n){
	/*
	 * This method computes the largest integer $k$ such that $2^k \leq n < 2^{k+1}$.
	 * 
	 * The method uses the following recurrence relation:
	 * 
	 * $k = 0$ if $n = 1$
	 * $k = 1 + computeBinaryLog(n/2)$ if $n > 1$ and $n$ is odd
	 * $k = 1 + computeBinaryLog(n/2 - 1)$ if $n > 1$ and $n$ is even
	 * 
	 * where $n/2$ and $n/2 - 1$ are floored division.
	 */

	if (n == 1) {
		return 0;
	} else if (n > 1 && n % 2 == 1) {
		return 1 + computeBinaryLog(n / 2);
	} else if (n > 1 && n % 2 == 0) {
		return 1 + computeBinaryLog(n / 2 - 1);
	} else {
		throw new IllegalArgumentException("n should be a positive integer");
	}
}

