private Node selectOnOuterFace(Predicate<Node> predicate,Node start,Node stop,int dir) {
    Node current = start;
    do {
        Node next = current.getNext(dir);
        if (next == stop || predicate.test(next)) {
            return next;
        }
        current = next;
    } while (current != start);

    return stop;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator result = new OuterFaceCirculator(start);
    while (result.hasNext()) {
        if (predicate.test(result.next())) {
            return result;
        }
        if (result.next() == stop) {
            return result;
        }
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate,Node start,Node stop,int dir){
    if(dir == 0){
        return new OuterFaceCirculator(start, stop);
    }

    if(predicate.test(start)){
        return new OuterFaceCirculator(start, start);
    }

    Node current = start.getNext(dir);
    while(current != stop){
        if(predicate.test(current)){
            return new OuterFaceCirculator(current, current);
        }
        current = current.getNext(dir);
    }

    return new OuterFaceCirculator(stop, stop);
}

public class OuterFaceCirculator {
    private Node start;
    public OuterFaceCirculator(Node start) {
        this.start = start;
    }

    public Node next() {
        // Rotate the start node in the clockwise direction
        start = start.next(1);
        return start;
    }
}

