public static String deleteAny(String inString, String charsToDelete) {
    // return the original string if there are no characters to delete
    if (charsToDelete.length() == 0) {
        return inString;
    }

    // create a set of characters to delete
    Set<Character> charactersToDelete = new HashSet<>();
    for (int i = 0; i < charsToDelete.length(); i++) {
        charactersToDelete.add(charsToDelete.charAt(i));
    }

    // create a new string builder to store the result
    StringBuilder outString = new StringBuilder();

    // loop through the input string and check each character
    for (int i = 0; i < inString.length(); i++) {
        // if the character is not in the set of characters to delete, add it to the result string builder
        if (!charactersToDelete.contains(inString.charAt(i))) {
            outString.append(inString.charAt(i));
        }
    }

    // return the resulting string
    return outString.toString();
}

