public byte readByte() throws IOException {

  // Check if there is still data available in the buffer
  if (this.position < this.buffer.capacity()) {
    // Return the next byte from the buffer
    return this.buffer.get(this.position++);
  }

  // Refill the buffer by reading from the underlying input stream
  this.buffer.rewind();
  this.inputStream.read(this.buffer);

  // Check if the end of the stream has been reached
  if (this.buffer.limit() == 0) {
    throw new IOException("No more data available");
  }

  // Update the position and return the first byte in the buffer
  this.position = 1;
  return this.buffer.get(0);
}

