private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        int bound = bounds.get(i);
        sum += bound;
        suffixSum.add((int) sum);
    }
    return new Pair<>(suffixSum, sum);
}

private static Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize the suffix sum and the sum of all elements to 0
    long suffixSum = 0L;
    long allElementsSum = 0L;

    // Iterate over the list of bounds
    for (int i = 0; i < bounds.size(); i++) {
        // Add the current bound to the sum of all elements
        allElementsSum += bounds.get(i);

        // If the current bound is non-zero, add it to the suffix sum
        if (bounds.get(i) != 0) {
            suffixSum += bounds.get(i);
        }
    }

    // Return the computed pair of suffix sum list and the sum of all elements
    return new Pair<>(Collections.singletonList((int) suffixSum), allElementsSum);
}

