public ByteVector putInt(int intValue) {
    // Check if the buffer needs to be enlarged
    if (size() < 4) {
        // Enlarge the buffer by doubling its current size
        int newSize = 2 * size();
        if (newSize < 4) {
            newSize = 4;
        }
        grow(newSize - size());
    }

    // Write the int value to the buffer
    for (int i = 0; i < 4; i++) {
        int shift = (3 - i) * 8;
        byte value = (byte) ((intValue >> shift) & 0xFF);
        add(value);
    }

    return this;
}

