private static boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Add all the vertices to a set
    Set<V>verticesSet = new HashSet<V>(vertices);
    // Check if the number of vertices is equal to the number of edges
    if(verticesSet.size() == (verticesSet.size()-1)*(verticesSet.size()-2)/2){
        // Fill each vertex's adjacent list
        for(V vertex : verticesSet){
            // Get all the vertices adjacent to the current vertex
            Set<V>adjacentVertices = graph.getNeighbors(verticesSet);
            // Check if every vertex in the adjacent set is also contained in the original set
