static <E> boolean isConnected(Graph<V, E> graph) {
    // Check if the graph is connected by performing a BFS from each vertex
    for (V vertex : graph.vertexSet()) {
        if (!isConnected(graph, vertex)) {
            return false;
        }
    }

    return true;
}

static <E> boolean isConnected(Graph<V, E> graph, V vertex) {
    // Initialize a set to keep track of visited vertices
    Set<V> visited = new HashSet<>();

    // Perform a BFS starting from the given vertex
    Queue<V> queue = new LinkedList<>();
    queue.offer(vertex);
    visited.add(vertex);
    while (!queue.isEmpty()) {
        V current = queue.poll();
        for (E adj : graph.adjacentEdgesOf(current)) {
            V neighbor = graph.getEdgeTarget(adj);
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.offer(neighbor);
            }
        }
    }

    // Check if all vertices are visited
    return visited.containsAll(graph.vertexSet());
}

