protected void append(LoggingEvent event) {

    // Get the connected clients
    Collection<Socket> clients = getConnectedClients();

    // Loop through each client and write the event to it
    for (Socket client : clients) {
        try {
            // Create an output stream for the client
            OutputStream outputStream = client.getOutputStream();

            // Write the event to the output stream
            outputStream.write(event.getMessage().getBytes());

            // Flush the output stream to ensure the event is written to the client
            outputStream.flush();

        } catch (IOException e) {
            // If an exception occurs while writing to the client, close the connection
            closeConnection(client);
        }
    }
}

