public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Skip comments and empty lines
            if (line.startsWith("#") || line.trim().isEmpty()) {
                continue;
            }

            // Parse the line into a ThreadSnapshot object
            String[] parts = line.split(" ");
            String threadName = parts[0];
            long threadId = Long.parseLong(parts[1]);
            long startTime = Long.parseLong(parts[2]);
            long endTime = Long.parseLong(parts[3]);
            long sleepTime = Long.parseLong(parts[4]);
            boolean isSleeping = Boolean.parseBoolean(parts[5]);
            ThreadSnapshot snapshot = new ThreadSnapshot(threadName, threadId, startTime, endTime, sleepTime, isSleeping);

            // Check if the snapshot falls within the specified time range
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range.contains(snapshot.getStartTime())) {
                    inRange = true;
                    break;
                }
            }

            // If the snapshot falls within the specified time range, add it to the list
            if (inRange) {
                snapshots.add(snapshot);
            }
        }
    }
    return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (InputStream is = new FileInputStream(file)) {
        BufferedReader reader = new BufferedReader(new InputStreamReader(is));
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith("ThreadSnapshot")) {
                // extract thread id and snapshot start time from line
                int threadId = Integer.parseInt(line.substring("ThreadSnapshot".length(), line.indexOf(" ")));
                long startTime = Long.parseLong(line.substring(line.indexOf(" "));
                // create a new ThreadSnapshot object for the current thread
                ThreadSnapshot snapshot = new ThreadSnapshot(threadId, startTime);
                // read next line to get the snapshot end time
                line = reader.readLine();
                if (line != null) {
                    // extract snapshot end time from line
                    long endTime = Long.parseLong(line.substring("SnapshotEnd".length(), line.indexOf(" ")));
                    // add time range information to the snapshot
                    snapshot.addTimeRange(new ProfileAnalyzeTimeRange(startTime, endTime));
                }
                // add the created snapshot to the list of snapshots
                snapshots.add(snapshot);
            }
        }
    }
    return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    try (RandomAccessFile fileHandle = new RandomAccessFile(file, "r")) {
        // Create a BufferedReader object to read the file contents
        BufferedReader reader = new BufferedReader(new FileReader(file));

        // Read the file line by line
        String line;
        while ((line = reader.readLine()) != null) {
            // Match the line against the pattern to extract the time and snapshot ID
            Matcher matcher = Pattern.compile("time\\s+(\\d+)\\s+snapshot\\s+(\\d+)").matcher(line);
            if (matcher.find()) {
                // Extract the time and snapshot ID
                long time = Long.parseLong(matcher.group(1));
                int snapshotID = Integer.parseInt(matcher.group(2));

                // If the time range is within the specified time range, add the snapshot
                for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                    if (timeRange.getStartTime() <= time && time <= timeRange.getEndTime()) {
                        ThreadSnapshot snapshot = new ThreadSnapshot(snapshotID, time);
                        threadSnapshots.add(snapshot);
                    }
                }
            }
        }
    }

    return threadSnapshots;
}

public static List<ThreadSnapshot> loadThreadSnapshotsWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
