try (RandomAccessFile raf = new RandomAccessFile(file, "r")) {
raf.seek(0);
while (raf.getFilePointer() < raf.length()) {
int profileSize = raf.readInt();
if (profileSize > 0) {
byte[] profileData = new byte[profileSize];
raf.readFully(profileData);
BufferedByteReader reader = new BufferedByteReader(profileData);
List<ProfileAnalyzeTimeRange> timeRanges = reader.readProfileAnalyzeTimeRanges();
if (timeRanges != null && !timeRanges.isEmpty()) {
ThreadSnapshot snapshot = new ThreadSnapshot();
snapshot.setTraceId(reader.readString());
snapshot.setTimestamp(reader.readLong());
snapshot.setDuration(reader.readLong());
snapshot.setCPUUsageRate(reader.readFloat());
snapshot.setThreadName(reader.readString());
snapshot.setThreadId(reader.readLong());
snapshot.setThreadState(reader.readString());
snapshot.setThreadPriority(reader.readInt());
snapshot.setStackTrace(reader.readStackTrace());
for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
if (timeRange.getStartTime() >= 0 && timeRange.getEndTime() >= 0 && timeRange.getStartTime() < snapshot.getDuration() && timeRange.getEndTime() < snapshot.getDuration()) {
timeRange.setDuration(snapshot.getDuration() - timeRange.getStartTime() - timeRange.getEndTime());
} else if (timeRange.getStartTime() == -1 && timeRange.getEndTime() == -1) {
timeRange.setDuration(snapshot.getDuration());
}
}
snapshots.add(snapshot);
}
}
}
}
